package com.clock.wallpaper;
import android.app.*;import android.content.*;import android.net.Uri;import android.os.*;import android.provider.Settings;import android.view.*;import android.widget.*;
public class PermissionActivity extends Activity { @Override public void onCreate(Bundle b){super.onCreate(b);LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(32,32,32,32);TextView t=new TextView(this);t.setText("Clock — разрешение\n\nЭтот отдельный экран нужен только для разрешения показа заставки поверх других приложений. Основные настройки Clock не используются.");t.setTextSize(18);box.addView(t);Button go=new Button(this);go.setText("Открыть разрешение поверх приложений");go.setOnClickListener(v->{try{if(Build.VERSION.SDK_INT>=23)startActivity(new Intent(Settings.ACTION_MANAGE_OVERLAY_PERMISSION, Uri.parse("package:"+getPackageName())));else startActivity(new Intent(Settings.ACTION_SETTINGS));}catch(Exception e){startActivity(new Intent(Settings.ACTION_MANAGE_APPLICATIONS_SETTINGS));}});box.addView(go);Button close=new Button(this);close.setText("Закрыть");close.setOnClickListener(v->finish());box.addView(close);setContentView(box);}}
